import assert from 'node:assert/strict';
import test from 'node:test';
import { readFile } from 'node:fs/promises';
import { Color } from 'three';
import { createPointcloudLayer, createPointcloudPanel, validatePointcloudPreview } from '../src/pointcloud-panel.js';

// Generated by the actual Python pointcloud_preview helper from 100 rows of
// arange(300).reshape(-1, 3) / 1000, with rejected original indices 4 and 99.
const stratifiedPreview = JSON.parse(await readFile(new URL('./fixtures/pointcloud-stratified.json', import.meta.url), 'utf8'));

function preview(overrides = {}) {
  return {
    source: 'registered_rgbd', generation: 1, scene_token: 'scene-1', observation_id: 'rgbd-1', checkpoint: 'fine',
    points_world_m: [[.2, -.3, .7], [.21, -.3, .71], [.5, .2, .9]], kept_mask: [true, false, true],
    cluster_labels: [0, -1, 1], counts: { input: 3, kept: 2, rejected: 1 }, total_point_count: 3,
    preview_sampling: 'uniform_original_indices', ...overrides,
  };
}

function near(actual, expected) {
  actual.forEach((value, index) => assert.ok(Math.abs(value - expected[index]) < 1e-7));
}

function mappedPreview() {
  return preview({ camera_ids: ['1', '2', '3'], pixels_rc: [[10, 20], [11, 21], [12, 22]], cameras: {},
    collision_scene: { status: 'available', frame: 'world', units: 'm', generation: 1,
      scene_token: 'scene-1', observation_id: 'rgbd-1',
      voxel_layers: [{ name: 'background', role: 'background', enabled: true, provenance: 'mapper_tsdf_surface_voxels',
        pose_wxyz: [.5, 0, .8, 1, 0, 0, 0], dims_m: [1, 1, 1], voxel_size_m: .01,
        surface_voxel_size_m: .01, surface_centers_world_m: [[.6, .1, .7]],
        mapper_surface_preview_count: 1, displayed_surface_count: 1,
        esdf: { cell_count: 1000000, shape_xyz: [100, 100, 100], sample_flat_indices: [123], sample_distances_m: [-.2] } }],
      table: { name: 'semantic_table_forbidden', enabled: true, provenance: 'inferred_ransac_support_completion',
        model: { pose: [.5, 0, .45, 1, 0, 0, 0], dims: [.8, .6, .305] }, ransac_inlier_count: 100,
        support_plane: { normal_xyz: [0, 0, 1], offset_m: -.6,
          observed_polygon_xy_m: [[.2, -.2], [.8, -.2], [.8, .2]] } },
      coverage: { full_environment_coverage: false, unknown_space_motion_gate: false }, mesh_layers: {} } });
}

test('collision display uses actual mapper voxels and inferred cuboid, never raw cloud bounds', () => {
  const layer = createPointcloudLayer();
  const data = mappedPreview();
  layer.update(data, 'collision');
  const voxels = layer.object.children.find(child => child.name === 'background');
  assert.equal(voxels.isInstancedMesh, true);
  assert.equal(voxels.count, 1);
  const table = layer.object.children.find(child => child.name === 'semantic_table_forbidden');
  near(table.position.toArray(), data.collision_scene.table.model.pose.slice(0, 3));
  near(table.scale.toArray(), [.8, .6, .305]);
  assert.equal(table.userData.provenance, 'inferred_ransac_support_completion');
  assert.equal(layer.object.children.some(child => child.isPoints), false);
  layer.dispose();
});

test('collision scene preview rejects stale map identity and camera provenance row mismatch', () => {
  const data = mappedPreview();
  data.collision_scene.scene_token = 'old-map';
  assert.throws(() => validatePointcloudPreview(data), /场景/);
  assert.throws(() => validatePointcloudPreview({ ...mappedPreview(), camera_ids: ['1'] }), /相机/);
});

function shellPreview() {
  const data = mappedPreview();
  data.collision_scene.cuboid_layers = [{name: 'semantic_instance::bin::bin_shell::wall_x_minus',
    enabled: true, role: 'bin_shell_completion', provenance: 'measured_planes_and_user_bin_dimensions',
    instance_id: 'bin', observation_id: data.observation_id, generation: data.generation,
    model: {pose: [.056, .6, .5, 1, 0, 0, 0], dims: [.012, .4, .2]}}];
  return data;
}

test('derived bin walls are visible as thin cuboids and keep measured voxel inputs unchanged', () => {
  const data = shellPreview();
  const before = structuredClone(data);
  const layer = createPointcloudLayer();
  layer.update(data, 'collision');
  const wall = layer.object.children.find(child => child.name === data.collision_scene.cuboid_layers[0].name);
  assert.ok(wall);
  assert.deepEqual(wall.scale.toArray(), [.012, .4, .2]);
  assert.deepEqual(wall.position.toArray(), [.056, .6, .5]);
  assert.equal(wall.userData.provenance, 'measured_planes_and_user_bin_dimensions');
  assert.equal(wall.userData.instanceId, 'bin');
  assert.deepEqual(data, before);
  layer.dispose();
});

test('derived bin preview rejects stale or unlabelled synthetic geometry', () => {
  for (const change of [{generation: 99}, {observation_id: 'old'}, {provenance: 'registered_rgbd'},
    {enabled: 'true'}, {instance_id: null}, {model: {pose: [0, 0, 0, 1, 0, 0, 0], dims: [-1, 1, 1]}}]) {
    const data = shellPreview();
    Object.assign(data.collision_scene.cuboid_layers[0], change);
    assert.throws(() => validatePointcloudPreview(data), /补全/);
  }
});

test('an instance-only collision scene colors its first layer as an instance, not a missing background', () => {
  const layer = createPointcloudLayer();
  const data = mappedPreview();
  data.collision_scene.voxel_layers[0].name = 'semantic_instance::bin';
  data.collision_scene.voxel_layers[0].role = 'semantic_instance';
  layer.update(data, 'collision');
  const voxels = layer.object.children.find(child => child.isInstancedMesh);
  assert.equal(voxels.material.color.getHexString(), 'ffb05c');
  assert.equal(voxels.count, 1);
  layer.dispose();
});

test('raw overlay retains all measured coordinates including rejected samples without changing the payload', () => {
  const data = preview();
  const before = structuredClone(data);
  const layer = createPointcloudLayer();
  layer.update(data);
  const points = layer.object.children[0];
  assert.equal(points.isPoints, true);
  near([...points.geometry.getAttribute('position').array], data.points_world_m.flat());
  near([...points.geometry.getAttribute('color').array],
    [new Color('#a7b3c4'), new Color('#a7b3c4'), new Color('#a7b3c4')].flatMap(color => color.toArray()));
  assert.equal(points.material.depthTest, false);
  assert.deepEqual(data, before);
  layer.dispose();
});

test('raw display does not require DBSCAN labels or per-point camera metadata', () => {
  const layer = createPointcloudLayer();
  layer.update(preview({ cluster_labels: null }), 'raw');
  assert.equal(layer.object.children[0].geometry.getAttribute('position').count, 3);
  const rawColors = [...layer.object.children[0].geometry.getAttribute('color').array];
  near(rawColors, Array.from({ length: 3 }, () => new Color('#a7b3c4').toArray()).flat());
  layer.dispose();
});

test('replacing or clearing an overlay disposes its GPU resources', () => {
  const layer = createPointcloudLayer();
  layer.update(preview());
  const old = layer.object.children[0];
  const disposed = [];
  for (const resource of [old.geometry, old.material]) resource.addEventListener('dispose', () => disposed.push(resource));
  layer.update(preview(), 'raw');
  assert.equal(disposed.length, 2);
  layer.clear();
  assert.equal(layer.object.children.length, 0);
});

test('preview validation rejects malformed provenance, mask, counts, sample limits and coordinates', () => {
  for (const invalid of [
    { source: 'editor' }, { observation_id: null }, { generation: -1 },
    { points_world_m: [[NaN, 0, 0]] }, { kept_mask: [true, false] }, { kept_mask: [1, false, true] },
    { counts: { input: 3, kept: 3, rejected: 1 } }, { counts: { input: 3, kept: 3, rejected: 0 } },
    { total_point_count: 2 }, { cluster_labels: [0, -2, 1] }, { cluster_labels: [0] },
    { preview_sampling: 'synthesized_points' },
    { points_world_m: Array.from({ length: 30001 }, () => [0, 0, 0]) },
  ]) assert.throws(() => validatePointcloudPreview(preview(invalid)), undefined, JSON.stringify(invalid).slice(0, 100));
  assert.doesNotThrow(() => validatePointcloudPreview(preview({ counts: { input: 100, kept: 60, rejected: 40 }, total_point_count: 100 })));
});

function harness() {
  function node(tagName) {
    return { tagName, children: [], textContent: '', value: '', listeners: {},
      append(...children) { this.children.push(...children); },
      replaceChildren(...children) { this.children = children; },
      addEventListener(kind, listener) { this.listeners[kind] = listener; },
    };
  }
  const container = node('div');
  const status = node('p');
  const requests = [];
  const overlays = [];
  const environmentVisibility = [];
  const panel = createPointcloudPanel(container, status, {
    document: { createElement: node },
    request(path, body) { return new Promise((resolve, reject) => requests.push({ path, body, resolve, reject })); },
    onOverlay: overlay => overlays.push(overlay),
    onEnvironmentVisible: visible => environmentVisibility.push(visible),
  });
  function descendants(parent = container) { return parent.children.flatMap(child => [child, ...descendants(child)]); }
  return { panel, requests, overlays, environmentVisibility, container, status,
    byTag(tag) { return descendants().filter(child => child.tagName === tag); },
    text() { return [status, ...descendants()].map(child => child.textContent).join('\n'); },
  };
}

test('panel offers only raw RGBD and mapped surface views, with an explicit ESDF display limit', async () => {
  const ui = harness();
  const pending = ui.panel.setOpen(true);
  ui.requests[0].resolve(mappedPreview());
  await pending;
  assert.deepEqual(ui.byTag('option').map(option => option.value), ['raw', 'collision']);
  assert.equal(ui.byTag('select')[0].value, 'raw');
  const selector = ui.byTag('select')[0];
  selector.value = 'collision';
  selector.listeners.change();
  assert.match(ui.text(), /TSDF 表面/);
  assert.match(ui.text(), /未绘制完整 ESDF 距离场/);
  ui.panel.dispose();
});

test('simulation visibility stays hidden through display changes and refresh, then restores on close', async () => {
  const ui = harness();
  const pending = ui.panel.setOpen(true);
  ui.requests[0].resolve(mappedPreview());
  await pending;
  const environment = ui.byTag('button').find(button => button.textContent === '隐藏仿真物体');
  assert.ok(environment);
  environment.listeners.click();
  assert.equal(ui.environmentVisibility.at(-1), false);
  assert.equal(environment.ariaPressed, 'true');
  ui.byTag('button').find(button => button.textContent === '显示点云').listeners.click();
  const selector = ui.byTag('select')[0];
  selector.value = 'collision';
  selector.listeners.change();
  assert.ok(ui.overlays.at(-1).children.some(child => child.name === 'semantic_table_forbidden'));
  const refreshed = ui.panel.refresh();
  ui.requests[1].resolve(mappedPreview());
  await refreshed;
  assert.equal(ui.environmentVisibility.at(-1), false);
  assert.equal(ui.requests.length, 2);
  ui.panel.setOpen(false);
  assert.equal(ui.environmentVisibility.at(-1), true);
  assert.equal(environment.ariaPressed, 'false');
  assert.equal(ui.overlays.at(-1), null);
  ui.panel.dispose();
});

test('panel exposes real collision layers, inferred support and unknown-space limitation', async () => {
  const ui = harness();
  const pending = ui.panel.setOpen(true);
  ui.requests[0].resolve(mappedPreview());
  await pending;
  assert.match(ui.text(), /当前没有未知空间运动门禁/);
  assert.match(ui.text(), /推断桌体：RANSAC 100/);
  assert.match(ui.text(), /ESDF 1000000 单元/);
  const option = ui.byTag('option').find(item => item.value === 'collision');
  assert.equal(option.disabled, false);
  const selector = ui.byTag('select')[0];
  selector.value = 'collision';
  selector.listeners.change();
  ui.byTag('button').find(button => button.textContent === '显示点云').listeners.click();
  assert.ok(ui.overlays.at(-1).children.some(child => child.isInstancedMesh));
  ui.panel.dispose();
});

test('the backend-generated stratified fixture retains aligned original rows and explains its non-proportional display', async () => {
  const ui = harness();
  const pending = ui.panel.setOpen(true);
  ui.requests[0].resolve(stratifiedPreview);
  await pending;
  ui.byTag('button').find(button => button.textContent === '显示点云').listeners.click();
  assert.ok(ui.overlays.at(-1));
  assert.match(ui.text(), /分层抽样/);
  assert.match(ui.text(), /预览中保留 18.*剔除 2/);
  assert.match(ui.text(), /不代表全量比例/);
  assert.match(ui.text(), /原始 100.*保留 98.*剔除 2/);
  const indices = stratifiedPreview.original_point_indices;
  assert.deepEqual(indices, [...indices].sort((a, b) => a - b));
  assert.ok(indices.includes(4) && indices.includes(99));
  indices.forEach((originalIndex, index) => {
    assert.deepEqual(stratifiedPreview.points_world_m[index], [0, 1, 2].map(axis => (3 * originalIndex + axis) / 1000));
    assert.equal(stratifiedPreview.kept_mask[index], ![4, 99].includes(originalIndex));
    assert.equal(stratifiedPreview.cluster_labels[index], originalIndex);
  });
  assert.equal(ui.overlays.at(-1).children[0].geometry.getAttribute('position').count, 20);
  ui.panel.dispose();
});

test('stratified previews require sorted unique aligned original indices within the full cloud', () => {
  for (const indices of [undefined, [0, 1], [0, 0, 2], [1, 0, 2], [-1, 1, 2], [0, 1, 3]]) {
    assert.throws(() => validatePointcloudPreview(preview({
      preview_sampling: 'stratified_original_indices', original_point_indices: indices,
    })));
  }
  assert.doesNotThrow(() => validatePointcloudPreview(preview({
    preview_sampling: 'stratified_original_indices', original_point_indices: [0, 1, 2],
  })));
});

test('panel only reads the saved snapshot when opened or manually refreshed, and full counts stay distinct from sampled points', async () => {
  const ui = harness();
  ui.panel.setGeneration(1);
  assert.equal(ui.requests.length, 0);
  await ui.panel.refresh();
  assert.equal(ui.requests.length, 0);
  const pending = ui.panel.setOpen(true);
  assert.equal(ui.requests[0].path, '/api/perception-preview');
  assert.equal(ui.requests[0].body, undefined);
  assert.equal(ui.panel.refresh(), pending);
  ui.requests[0].resolve(preview({ counts: { input: 100, kept: 60, rejected: 40 }, total_point_count: 100 }));
  await pending;
  assert.match(ui.text(), /rgbd-1/);
  assert.match(ui.text(), /fine/);
  assert.match(ui.text(), /100/);
  assert.match(ui.text(), /60/);
  assert.match(ui.text(), /40/);
  assert.match(ui.text(), /3.*100/);
  assert.match(ui.text(), /抽样/);
  assert.equal(ui.overlays.at(-1), null);
  ui.byTag('button').find(button => button.textContent === '显示点云').listeners.click();
  assert.ok(ui.overlays.at(-1));
  assert.equal(ui.overlays.at(-1).children[0].geometry.getAttribute('position').count, 3);
  assert.equal(ui.requests.length, 1);
  ui.panel.setOpen(false);
  assert.equal(ui.overlays.at(-1), null);
  ui.panel.dispose();
});

test('hiding the overlay preserves inspection and remains hidden through mode changes and an in-flight refresh', async () => {
  const ui = harness();
  const pending = ui.panel.setOpen(true);
  ui.requests[0].resolve(mappedPreview());
  await pending;
  assert.equal(ui.overlays.at(-1), null);
  const toggle = ui.byTag('button').find(button => button.textContent === '显示点云');
  assert.ok(toggle);
  toggle.listeners.click();
  assert.ok(ui.overlays.at(-1));
  assert.equal(toggle.ariaPressed, 'true');
  assert.equal(toggle.textContent, '隐藏点云');

  const refreshed = ui.panel.refresh();
  toggle.listeners.click();
  assert.equal(ui.overlays.at(-1), null);
  assert.equal(toggle.ariaPressed, 'false');
  assert.match(ui.text(), /全量点数：原始 3/);
  const mode = ui.byTag('select')[0];
  mode.value = 'collision';
  mode.listeners.change();
  assert.equal(ui.overlays.at(-1), null);
  assert.match(ui.text(), /TSDF 表面/);
  const next = mappedPreview();
  next.observation_id = next.collision_scene.observation_id = 'rgbd-2';
  ui.requests[1].resolve(next);
  await refreshed;
  assert.equal(ui.overlays.at(-1), null);
  assert.match(ui.text(), /rgbd-2/);
  assert.equal(toggle.textContent, '显示点云');

  toggle.listeners.click();
  assert.equal(ui.overlays.at(-1).children[0].isInstancedMesh, true);
  assert.equal(ui.requests.length, 2);
  ui.panel.dispose();
});

test('folding the panel during a refresh prevents late results or reopening from restoring the overlay', async () => {
  const ui = harness();
  const pending = ui.panel.setOpen(true);
  ui.requests[0].resolve(preview());
  await pending;
  const toggle = ui.byTag('button').find(button => button.textContent === '显示点云');
  assert.ok(toggle);
  toggle.listeners.click();
  const refreshed = ui.panel.refresh();
  ui.panel.setOpen(false);
  assert.equal(ui.overlays.at(-1), null);
  ui.requests[1].resolve(preview());
  await refreshed;
  assert.equal(ui.overlays.at(-1), null);
  const reopened = ui.panel.setOpen(true);
  ui.requests[2].resolve(preview());
  await reopened;
  assert.equal(ui.overlays.at(-1), null);
  assert.equal(toggle.textContent, '显示点云');
  ui.panel.dispose();
});

test('manual refresh is serial and collision display requires a real mapped snapshot', async () => {
  const ui = harness();
  const pending = ui.panel.setOpen(true);
  ui.requests[0].resolve(preview({ cluster_labels: null }));
  await pending;
  assert.equal(ui.byTag('option').find(option => option.value === 'collision').disabled, true);
  assert.match(ui.text(), /实际碰撞地图暂不可用/);
  const refreshed = ui.panel.refresh();
  ui.panel.refresh();
  assert.equal(ui.requests.length, 2);
  ui.requests[1].resolve(mappedPreview());
  await refreshed;
  assert.equal(ui.byTag('option').find(option => option.value === 'collision').disabled, false);
  ui.byTag('select')[0].value = 'collision';
  ui.byTag('select')[0].listeners.change();
  assert.match(ui.text(), /未绘制完整 ESDF/);
  const unavailable = ui.panel.refresh();
  ui.requests[2].resolve(preview());
  await unavailable;
  assert.equal(ui.byTag('select')[0].value, 'raw');
  assert.equal(ui.byTag('option').find(option => option.value === 'collision').disabled, true);
  ui.panel.dispose();
});

test('reset clears the overlay and rejects an in-flight or newly returned preview from an older generation', async () => {
  const ui = harness();
  ui.panel.setGeneration(1);
  const pending = ui.panel.setOpen(true);
  ui.panel.setGeneration(2);
  ui.requests[0].resolve(preview());
  await pending;
  assert.equal(ui.overlays.at(-1), null);
  const stale = ui.panel.refresh();
  ui.requests[1].resolve(preview());
  await stale;
  assert.equal(ui.overlays.at(-1), null);
  assert.match(ui.status.textContent, /场景/);
  ui.panel.dispose();
});

test('unavailable or invalid saved previews clear displayed points and explain the failure', async () => {
  const ui = harness();
  const pending = ui.panel.setOpen(true);
  ui.requests[0].reject(new Error('perception_preview_unavailable'));
  await pending;
  assert.equal(ui.overlays.at(-1), null);
  assert.match(ui.status.textContent, /尚无/);
  const invalid = ui.panel.refresh();
  ui.requests[1].resolve(preview({ source: 'editor' }));
  await invalid;
  assert.equal(ui.overlays.at(-1), null);
  assert.match(ui.status.textContent, /读取失败/);
  ui.panel.dispose();
});
